def _message_from_constructor_envelope(message: dict) -> BaseMessage:
    """Reconstruct a message from a Serializable constructor-envelope.

    The class name is read from the last element of the `id` list and the
    message is rebuilt from `kwargs`. Chunk variants (e.g. `HumanMessageChunk`)
    are coerced to their parent (non-chunk) message type.

    Args:
        message: A dict in the constructor-envelope format.

    Returns:
        The reconstructed message.

    Raises:
        ValueError: If the class name is unknown or unsupported.
    """
    class_name = message["id"][-1]
    kwargs = dict(message["kwargs"])

    # Chunk variants are coerced to their parent (non-chunk) message type.
    if isinstance(class_name, str) and class_name.endswith("Chunk"):
        class_name = class_name[: -len("Chunk")]

    if class_name == "HumanMessage":
        return HumanMessage(**kwargs)
    if class_name == "AIMessage":
        return AIMessage(**kwargs)
    if class_name == "SystemMessage":
        return SystemMessage(**kwargs)
    if class_name == "ToolMessage":
        additional_kwargs = kwargs.get("additional_kwargs") or {}
        if "artifact" in additional_kwargs:
            kwargs.setdefault("artifact", additional_kwargs["artifact"])
        return ToolMessage(**kwargs)
    if class_name == "FunctionMessage":
        return FunctionMessage(**kwargs)

